function origamiProcess(data,w,h,opts){
  opts=opts||{};
  var cell=opts.cell!=null?opts.cell:18;
  if(cell<6)cell=6; else if(cell>48)cell=48;
  var out=new Uint8ClampedArray(data.length);
  for(var gy=0;gy<h;gy+=cell) for(var gx=0;gx<w;gx+=cell){
    var cw=Math.min(cell,w-gx), ch=Math.min(cell,h-gy);
    var sr=0,sg=0,sb=0,n=0;
    for(var yy=gy;yy<gy+ch;yy++) for(var xx=gx;xx<gx+cw;xx++){ var p=(yy*w+xx)*4; sr+=data[p]; sg+=data[p+1]; sb+=data[p+2]; n++; }
    var r=Math.round(sr/n), g=Math.round(sg/n), b=Math.round(sb/n);
    for(var py=gy;py<gy+ch;py++) for(var px=gx;px<gx+cw;px++){
      var pp=(py*w+px)*4;
      var onDiag=(px-gx)===(py-gy); // main diagonal crease
      var onBorder=(px===gx||py===gy||px===gx+cw-1||py===gy+ch-1);
      var below=(py-gy)>(px-gx); // triangle B
      var mul = below?0.9:1.1;
      if(onDiag) mul=1.28; else if(onBorder) mul=0.6;
      out[pp]=r*mul; out[pp+1]=g*mul; out[pp+2]=b*mul; out[pp+3]=255;
    }
  }
  return out;
}

var EXPORTS={origamiProcess:origamiProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.OrigamiForgePure = EXPORTS; }
